    content: `## تمهيد

كيف يمكن للمنظمة مواءمة أهدافها الأمنية مع أهداف الأعمال وتصميم خارطة طريق استراتيجية قابلة للتنفيذ والقياس؟ يجيب هذا الفصل عن هذا التساؤل من خلال استعراض المكونات الأساسية للتخطيط الاستراتيجي لبرامج الأمن السيبراني، بدءاً من فهم بيئة المنظمة وتحديد ملفها التنظيمي، مروراً بتحليل الفجوات وتحديد الأولويات عبر **نموذج درجة الأولوية المرجحة**، ووصولاً إلى بناء **خارطة الطريق الأمنية** ومؤشرات قياس الأداء والمخاطر.

---page---

## استراتيجية الأمن السيبراني ومواءمة الأعمال (Strategic Alignment)

- **التخطيط الاستراتيجي لبرامج الأمن السيبراني**: العملية المنهجية التي تُبنى على استراتيجية إدارة المخاطر في المنظمة، وتتضمن القرارات على المستوى الاستراتيجي لكيفية إدارة كبار القادة للمخاطر التي تهدد العمليات والأصول والأفراد.
- **أهداف برنامج الأمن السيبراني**: المستهدفات الشاملة التي يضعها المسؤولون التنفيذيون وتنتقل تدريجياً إلى المديرين لتنفيذها عبر الخدمات والضوابط المشتركة.
- **مواءمة الأعمال والأمن السيبراني (Business Alignment)**: عملية ترتيب أولويات الإجراءات الأمنية والتواصل بشأنها بفعالية لضمان دعمها لغايات المنظمة، بالنظر في توقعات أصحاب المصلحة ومشهد التهديدات والمتطلبات النظامية.

> [!success]
> **مثال تطبيقي**: شركة مبيعات إلكترونية توائم أمنها مع أعمالها بتوجيه ميزانيتها لحماية أنظمة الدفع الإلكتروني أولاً، استجابةً لتوقعات عملائها بضمان سرية بياناتهم المالية واستمرارية عمليات الشراء.

---page---

## تحليل الفجوات ونموذج درجة الأولوية المرجحة (Weighted Priority Score Model)

عندما تشترك عدة أنظمة تنظيمية في نفس مستوى التأثير العام (مثلاً: جميعها مصنفة «متوسطة التأثير»)، كيف ترتب المؤسسة أولويات تخصيص الميزانية والموارد بينها؟

يعتمد كتاب المقرر **نموذج درجة الأولوية المرجحة (Weighted Priority Model)** الذي لا يعتمد على أوزان رقمية عشوائية، بل يقسم الأنظمة داخل مستوى التأثير الواحد إلى **ثلاث فئات فرعية تعمل كآلية ترجيح دقيقة**:

| مستوى التأثير الأساسي للنظام | الفئات الفرعية للترجيح داخل المستوى (من الأعلى للأدنى أولوية) | مثال تطبيقي للمقارنة والترجيح | قرار تخصيص الموارد |
| :--- | :--- | :--- | :--- |
| **أنظمة عالية التأثير (High Impact)** | **عالية-عالية** ثم **متوسطة-عالية** ثم **منخفضة-عالية** | نظام التحويلات المصرفية الفورية (عالية-عالية) مقابل نظام الأرشفة الائتمانية (متوسطة-عالية) | يُمول ويُحصن نظام التحويلات أولاً في الربع الأول |
| **أنظمة متوسطة التأثير (Moderate Impact)** | **عالية-متوسطة** ثم **متوسطة-متوسطة** ثم **منخفضة-متوسطة** | النظام المالي الداخلي (**عالية-متوسطة**) مقابل نظام الحضور والانصراف (**منخفضة-متوسطة**) | يفترض النظام المالي (عالية-متوسطة) أولوية أعلى من نظام الحضور |
| **أنظمة منخفضة التأثير (Low Impact)** | **عالية-منخفضة** ثم **متوسطة-منخفضة** ثم **منخفضة-منخفضة** | بوابة الأخبار العامة (عالية-منخفضة) مقابل نظام حجز قاعات الاجتماعات (منخفضة-منخفضة) | تُغطى بالضوابط المشتركة الأساسية |

---page---

## تصميم خارطة الطريق والمبادرات الأمنية (Security Roadmap & Initiatives)

**خارطة الطريق الأمنية (Security Roadmap)** هي خطة العمل ذات الأولوية التي تُطور لمعالجة الفجوات المحددة بين الملفين الحالي والمستهدف، وتدفع المنظمة نحو تحقيق ملفها التنظيمي المستهدف عبر مبادرات محددة المعالم والموارد:

| الربع السنوي | المرحلة الاستراتيجية | المبادرات الأمنية الرئيسية | المخرج القابل للقياس (Deliverable & Milestone) |
| :--- | :--- | :--- | :--- |
| **الربع الأول (Q1)** | **التأسيس والحوكمة وحصر الأصول** | اعتماد ميثاق الحوكمة، بناء سجل الأصول المصنف، وتحديث السياسات الأساسية | ميثاق معتمد، مصفوفة RACI، وسجل أصول مكتمل بنسبة 100% للأصول الحرجة |
| **الربع الثاني (Q2)** | **سد الفجوات الحرجة والتحصين** | تفعيل المصادقة الثنائية (MFA)، عزل النسخ الاحتياطية، وترقيع الثغرات الحرجة | تغطية 100% من الحسابات الحساسة بـ MFA ونسخ احتياطي مختبر |
| **الربع الثالث (Q3)** | **المراقبة المستمرة والتوعية** | ربط الخوادم بنظام مراقبة التنبيهات وتنفيذ حملات التوعية ضد التصيد | معالجة التنبيهات الحرجة خلال 15 دقيقة وتدريب 95% من الموظفين |
| **الربع الرابع (Q4)** | **التقييم المستقل والتحسين** | إجراء التدقيق الداخلي، اختبار خطة استمرارية الأعمال، وتحديث الملف التنظيمي | تقرير تدقيق مستقل، خطة POA&M محدثة، واعتماد المسؤول المخول |

---page---

## التنفيذ والتواصل ومؤشرات الأداء والمخاطر (KPIs & KRIs) ودورة التحسين

لضمان نجاح تنفيذ خارطة الطريق، تعتمد المؤسسة مقاييس واضحة ودورة تحسين مستمر (PDCA: Plan, Do, Check, Act):
- **مؤشرات الأداء الرئيسية (Key Performance Indicators - KPIs)**: تقيس مدى التقدم والكفاءة في تنفيذ أنشطة ومبادرات إدارة المخاطر (مثل: *نسبة الخوادم المحدثة أمنياً خلال 7 أيام*، أو *متوسط زمن الاستجابة للحوادث MTTR*).
- **مؤشرات المخاطر الرئيسية (Key Risk Indicators - KRIs)**: تقيس مستوى تعرض المنظمة لخطر محدد مقارنة بحدود شهية وتحمل المخاطر وتعمل كإنذار مبكر (مثل: *عدد الأنظمة الحرجة التي تعمل بدون نسخ احتياطي مختبر*، أو *تجاوز محاولات الاختراق اليومية للعتبة الحرجة*).`,
