    content: `## تمهيد

تختار المنظمة ضوابطها لتلبية متطلبات الأمن والخصوصية، ثم تحتاج إلى التحقق المنهجي من فاعلية هذه الضوابط في إدارة المخاطر. يتناول هذا الفصل ثلاثة محاور حاسمة: **كيف تتحقق المنظمة من أداء ضوابطها وفق التشريعات الوطنية (NCA ECC-2:2024 ونظام سدايا PDPL)؟ وكيف تكتشف فجوات الامتثال وتصححها عبر خطة العمل والمعالم (POA&M)؟ وكيف تقيس أداءها الأمني بمؤشرات واضحة تدعم التحسين المستمر؟**

---page---

## إدارة الامتثال وتصنيف الضوابط الأمنية الأربعة

- **متطلبات الامتثال (Compliance Requirements)**: الالتزامات القانونية والتنظيمية والتعاقدية المتعلقة بالأمن السيبراني وخصوصية البيانات، وفي مقدمتها في المملكة: **الضوابط الأساسية للأمن السيبراني (NCA ECC-1:2018 / ECC-2:2024)** و**نظام حماية البيانات الشخصية (PDPL)** الصادر عن سدايا.
- **الضابط الأمني (Security Control)**: تدبير حماية تختاره المنظمة وتنفذه لتلبية متطلبات الأمن والخصوصية وإدارة المخاطر، ثم يُقيّم لمعرفة صحة تنفيذه وفاعليته، ويتخذ القرار بشأن نتائج تقييمه **المسؤول المخول (Authorizing Official)**.

### الأنواع الأربعة للضوابط الأمنية في بيئة المؤسسة:
1. **ضوابط خاصة بالنظام (System-Specific Controls)**: تُصمم وتُنفذ لنظام واحد بعينه (مثل: التحقق بعامل ثانٍ مخصص عند الدخول إلى نظام الموارد البشرية).
2. **ضوابط مشتركة (Common Controls)**: يرثها النظام من جهة مركزية أو مزود خارجي، وتُقيّم منفصلة عن تقييم النظام الفردي (مثل: ضبط الدخول المادي إلى مركز بيانات المزود).
3. **ضوابط هجينة (Hybrid Controls)**: يشترك في تنفيذها مقدم الضابط المشترك ومالك النظام.
4. **ضوابط إدارة البرنامج (Program Management Controls)**: ضوابط مؤسسية شاملة تُطبق على مستوى برنامج الأمن السيبراني ككل (كاستراتيجية إدارة المخاطر وميثاق الحوكمة).

---page---

## التدقيق الأمني، الدليل الموضوعي، والعناصر الثلاثة لفاعلية الضابط

- **تقييم الضوابط / التدقيق الأمني (Control Assessment / Security Audit)**: فحص منهجي لتحديد مدى استيفاء الضوابط للمتطلبات، ويعتمد كلياً على **الدليل الموضوعي**.
- **الدليل الموضوعي (Objective Evidence)**: الوثائق والسجلات والمخرجات ونتائج الاختبارات الميدانية اللازمة لتقييم الضوابط.

### العناصر الثلاثة التي يجب أن يثبتها الدليل الموضوعي لفاعلية الضابط:
لا يكفي وجود وثيقة مكتوبة لإثبات الامتثال؛ بل يجب أن يغطي الدليل الموضوعي **العناصر الثلاثة للفاعلية**:
1. **أن الضابط نُفِّذ بصورة صحيحة (Implemented Correctly)** دون أخطاء في الإعدادات.
2. **أنه يعمل في بيئة التشغيل كما هو مقصود (Operating as Intended)** بصورة مستمرة.
3. **أنه ينتج النتيجة المطلوبة (Producing Desired Outcome)** للوفاء بمتطلبات الأمن والخصوصية.

> [!warning]
> **قاعدة ذهبية في التدقيق**: الإجراء المكتوب وحده يصف ما ينبغي أن يحدث، ولكنه **لا يثبت** أن الضابط يعمل فعلاً في بيئة التشغيل؛ فالدليل الموضوعي على عمل ضابط الدخول المادي هو **سجلات الدخول الإلكترونية للبوابات** إلى جانب نص السياسة.

---page---

## الإجراءات التصحيحية، النتائج الإيجابية الكاذبة، وخطة العمل والمعالم (POA&M)

عند اكتشاف قصور أثناء التدقيق، تتبع المنظمة مسار المعالجة المنظم:
- **النتائج الإيجابية الكاذبة (False Positives)**: ملاحظات يسجلها الفحص الآلي أو المبدئي كقصور ثم يتبين بعد التحقق الفني أن الضابط سليم؛ ويجب فرزها واستبعادها أولاً لعدم هدر الموارد.
- **الإجراء التصحيحي (Remediation Action)**: تدبير لمعالجة قصور الضوابط بناءً على تقارير التقييم، ويتراوح بين **معالجة أولية سريعة** للملاحظات التي يسهل إصلاحها فوراً (مثل إغلاق منافذ شبكة مفتوحة غير مستخدمة في اليوم نفسه)، و**معالجة مجدولة** للمخاطر التي تتطلب موارد ووقتاً.
- **خطة العمل والمعالم (Plan of Action and Milestones - POA&M)**: وثيقة تصف الإجراءات المخططة لتصحيح القصور، وتحدد مهامها، والموارد اللازمة لها، والمعالم (Milestones)، والتواريخ المجدولة للإنجاز، ويراجعها المسؤول المخول.

> [!error]
> **تنبيه مهم**: لا يُدرج في وثيقة POA&M القصورُ الذي يقبله المسؤول المخول رسمياً كـ **خطر متبقٍ (Accepted Residual Risk)**، بل يبقى موثقاً في تقارير التقييم وسجل المخاطر.

---page---

## قياس الأداء الأمني والمراقبة المستمرة (KPIs vs KRIs)

يقارن الجدول التالي بين مؤشر الأداء الرئيس (KPI) ومؤشر المخاطر الرئيس (KRI) كما ورد في كتاب المقرر:

| وجه المقارنة | مؤشر الأداء الرئيس (KPI) | مؤشر المخاطر الرئيس (KRI) |
| :--- | :--- | :--- |
| **الغرض الرئيسي** | متابعة التقدم نحو أهداف إدارة المخاطر وكفاءة أداء الضوابط والفرق | تتبع مستوى تعرض المنظمة لخطر محدد مقارنة بحدود شهية وتحمل المخاطر |
| **معيار الملاءمة** | يدعم قراراً إدارياً محدداً، وتتوافر بياناته، ويُبلَغ بوتيرة مناسبة | يرتبط بعتبة تحمل المخاطر (Risk Tolerance) ويطلق تنبيهاً عند اقتراب تجاوزها |
| **مثال لمؤشر ملائم** | «نسبة الخوادم المحدّثة أمنياً خلال 7 أيام» أو «نسبة الحوادث المحتواة ضمن المدة» | «عدد الأنظمة الحرجة المعرضة لثغرات غير مرقعة تتجاوز عتبة التحمل» |
| **مثال لمؤشر غير ملائم** | «عدد الاجتماعات الأمنية» (لا يدل على فاعلية أي ضابط) | مؤشر عام غير مربوط بحدود شهية المخاطر المعتمدة |`,
